mapper.select:
select t.template_id templateId, t.template_name templateName, t.event_way eventWay, t.community_id communityId, t.remark, t.create_time createTime, t.status_cd statusCd, etp.param_id paramId, etp.template_id templateId, etp.spec_cd specCd, etp.param_value paramValue, etp.community_id communityId, etp.create_time createTime, etp.status_cd statusCd, td.name eventWayName, etpk.spec_name specName from event_template t left join t_dict td on t.event_way = td.status_cd and td.table_name = 'event_template' and td.table_columns = 'event_way' left join event_template_param etp on t.template_id = etp.template_id and etp.status_cd = '0' left join event_template_param_key etpk on etp.spec_cd = etpk.spec_cd and t.event_way = etpk.event_way and etpk.status_cd = '0' where 1 =1
and t.template_name like concat('%', #{templateName}, '%')
and t.event_way= #{eventWay}
and t.remark= #{remark}
and t.status_cd= #{statusCd}
and t.template_id= #{templateId}
and t.community_id= #{communityId}
order by t.create_time desc
limit #{page}, #{row}

select
t.template_id templateId,
t.template_name templateName,
t.event_way eventWay,
t.community_id communityId,
t.remark,
t.create_time createTime,
t.status_cd statusCd,
td.name eventWayName
from event_template t
left join t_dict td on t.event_way = td.status_cd and td.table_name = 'event_template' and td.table_columns = 'event_way'
where 1 =1

    and t.template_name like concat('%', #{templateName}, '%')


    and t.event_way= #{eventWay}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.template_id= #{templateId}


    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

